from collections import deque
def regions(g,bgc):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==bgc and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; comp=[]
                border=False
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    if a in(0,H-1) or b in(0,W-1): border=True
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<H and 0<=y<W and g[x][y]==bgc and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                if not border: comps.append(comp)
    return comps
def rect(comp):
    rs=[a for a,b in comp]; cs=[b for a,b in comp]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    return len(comp)==(r1-r0+1)*(c1-c0+1)
def solve(g,bgc,fc):
    g=[r[:] for r in g]
    for comp in regions(g,bgc):
        if rect(comp):
            for a,b in comp: g[a][b]=fc
    return g
